import sys

def main():
    import sys
    input = sys.stdin.read().splitlines()
    n = int(input[0])
    greetings = input[1:]

    def is_stylish_subset(subset):
        for i in subset:
            for j in subset:
                if i != j and greetings[i] in greetings[j]:
                    return False
        return True

    max_size = 0
    best_subset = []

    for i in range(n):
        current_subset = [i]
        for j in range(n):
            if j != i and all(greetings[k] not in greetings[j] and greetings[j] not in greetings[k] for k in current_subset):
                current_subset.append(j)
        if len(current_subset) > max_size:
            max_size = len(current_subset)
            best_subset = current_subset

    print(max_size)
    print(" ".join(str(x + 1) for x in best_subset))

main()
